  `base_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `discounted_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `preferred_day` varchar(32) DEFAULT NULL,
  `preferred_time_slot` varchar(64) NOT NULL DEFAULT 'Morning (8:00 AM - 12:00 PM)',
